class PlacementState(str, Enum):
    INCLUDED = "included"
    EXCLUDED = "excluded"
    RELOCATING = "relocating"


class RelocationPhase(str, Enum):
    COPYING = "copying"
    DESTINATION_READY = "destination_ready"
    MOVING = "moving"
    COMMITTED = "committed"


class RelocationRecord(const.StrictModel):
    source_root: str
    destination_root: str
    staging_name: str | None = None
    phase: RelocationPhase


class CheckoutPlacement(const.StrictModel):
    """Sparse, machine-local placement record, keyed by stable box id."""

    schema_version: int = 1
    checkout_root: str
    state: PlacementState
    relocation: RelocationRecord | None = None

    @model_validator(mode="after")
    def validate_state(self):
        if self.schema_version != 1:
            raise ValueError(
                f"Unsupported checkout placement schema_version {self.schema_version}; upgrade Boxyard"
            )
        if (self.state == PlacementState.RELOCATING) != (self.relocation is not None):
            raise ValueError("relocating placement state requires relocation details, and only that state may have them")
        return self

    @property
    def authoritative_root(self) -> str:
        if self.state != PlacementState.RELOCATING:
            return self.checkout_root
        assert self.relocation is not None
        if self.relocation.phase == RelocationPhase.COMMITTED:
            return self.relocation.destination_root
        return self.relocation.source_root


