def placement_path(config: Config, box_id: str) -> Path:
    return config.placements_path / f"{box_id}.json"


def _atomic_json_write(path: Path, data: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.parent / f".{path.name}.{uuid.uuid4().hex}.tmp"
    try:
        with open(temp, "x", encoding="utf-8") as stream:
            json.dump(data, stream, indent=2, sort_keys=True)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if temp.exists():
            temp.unlink()


def save_placement(config: Config, box_id: str, placement: CheckoutPlacement) -> None:
    _atomic_json_write(placement_path(config, box_id), placement.model_dump(mode="json"))


def delete_placement(config: Config, box_id: str) -> None:
    path = placement_path(config, box_id)
    if path.exists():
        path.unlink()


def _legacy_placement(config: Config, box_meta: BoxMeta) -> CheckoutPlacement:
    """Permanent sparse-schema rule for pre-placement boxes.

    A missing record means the preferred root is ``default``. Existing DATA at
    user_boxes_path/<index> means included; otherwise excluded. This is the
    documented representation of legacy/single-root boxes, not a temporary shim.
    Every placement-changing mutation writes an explicit v1 record.
    """
    path = config.user_boxes_path / box_meta.index_name
    state = PlacementState.INCLUDED if path.is_dir() else PlacementState.EXCLUDED
    return CheckoutPlacement(checkout_root="default", state=state)


def load_placement(config: Config, box_meta: BoxMeta) -> CheckoutPlacement:
    path = placement_path(config, box_meta.box_id)
    if not path.exists():
        return _legacy_placement(config, box_meta)
    return CheckoutPlacement.model_validate_json(path.read_text(encoding="utf-8"))


def root_configuration_findings(config: Config) -> list[dict]:
    """Return duplicate/overlapping configured root findings without hiding them at load."""
    roots = config.configured_checkout_roots
    findings: list[dict] = []
    normalized: dict[Path, list[str]] = {}
    for name, root in roots.items():
        normalized.setdefault(root.path.resolve(strict=False), []).append(name)
    for path, names in normalized.items():
        if len(names) > 1:
            findings.append({"kind": "duplicate", "names": sorted(names), "path": path})
    items = sorted(
        ((name, root.path.resolve(strict=False)) for name, root in roots.items()),
        key=lambda item: len(item[1].parts),
    )
    for i, (outer_name, outer) in enumerate(items):
        for inner_name, inner in items[i + 1:]:
            if outer == inner:
                continue
            try:
                inner.relative_to(outer)
            except ValueError:
                continue
            findings.append({
                "kind": "overlap",
                "names": [outer_name, inner_name],
                "path": inner,
                "outer_path": outer,
            })
    return findings


def assert_root_configuration_safe(config: Config) -> None:
    findings = root_configuration_findings(config)
    if findings:
        details = "; ".join(
            f"{f['kind']} checkout roots {', '.join(f['names'])} at '{f['path']}'"
            for f in findings
        )
        raise ValueError(f"Unsafe checkout-root configuration: {details}. Run `boxyard doctor --no-remote`.")


def _unescape_mountinfo_path(value: str) -> str:
    # mountinfo escapes space, tab, newline and backslash as octal sequences.
    for escaped, literal in (("\\040", " "), ("\\011", "\t"), ("\\012", "\n"), ("\\134", "\\")):
        value = value.replace(escaped, literal)
    return value


def _linux_mounts() -> list[tuple[Path, str]]:
    mounts = []
    with open("/proc/self/mountinfo", encoding="utf-8") as stream:
        for line in stream:
            before, separator, after = line.rstrip("\n").partition(" - ")
            if not separator:
                continue
            fields = before.split()
            post = after.split()
            if len(fields) < 5 or len(post) < 2:
                continue
            mounts.append((Path(_unescape_mountinfo_path(fields[4])), post[1]))
    return mounts


def _guarded_root_status(name: str, root: CheckoutRootConfig) -> CheckoutRootStatus:
    assert root.mount_target is not None and root.filesystem_uuid is not None
    mount_target = root.mount_target.resolve(strict=False)
    if os.name != "posix" or not Path("/proc/self/mountinfo").is_file():
        return CheckoutRootStatus(
            name, root.path, False,
            "guarded checkout roots require Linux /proc/self/mountinfo on this platform",
            True, mount_target, root.filesystem_uuid,
        )
    match = next((source for target, source in _linux_mounts() if target.resolve(strict=False) == mount_target), None)
    if match is None:
        return CheckoutRootStatus(
            name, root.path, False,
            f"expected mount target '{mount_target}' is not an exact mounted target",
            True, mount_target, root.filesystem_uuid,
        )
    uuid_path = Path("/dev/disk/by-uuid") / root.filesystem_uuid
    expected_tokens = {f"UUID={root.filesystem_uuid}"}
    if uuid_path.exists():
        expected_tokens.add(str(uuid_path.resolve()))
    try:
        actual_source = str(Path(match).resolve()) if match.startswith("/") else match
    except OSError:
        actual_source = match
    if actual_source not in expected_tokens:
        return CheckoutRootStatus(
            name, root.path, False,
            f"mount target '{mount_target}' is backed by '{actual_source}', not filesystem UUID '{root.filesystem_uuid}'",
            True, mount_target, root.filesystem_uuid,
        )
    try:
        root.path.resolve(strict=False).relative_to(mount_target)
    except ValueError:
        return CheckoutRootStatus(
            name, root.path, False,
            f"checkout path '{root.path}' is not beneath verified mount target '{mount_target}'",
            True, mount_target, root.filesystem_uuid,
        )
    return CheckoutRootStatus(name, root.path, True, None, True, mount_target, root.filesystem_uuid)


def get_checkout_root_status(config: Config, name: str) -> CheckoutRootStatus:
    root = config.configured_checkout_roots.get(name)
    if root is None:
        raise ValueError(
            f"Unknown checkout root {name!r}. Configured roots: {', '.join(sorted(config.configured_checkout_roots))}"
        )
    if root.mount_target is not None:
        return _guarded_root_status(name, root)
    # An unguarded root is an explicit declaration that the ordinary local path
    # may be created. Availability is configuration policy, not inferred from
    # whether an attacker/automounter happened to create a directory.
    return CheckoutRootStatus(name, root.path, True, None, False, None, None)


def require_checkout_root(config: Config, name: str, *, create: bool = False) -> CheckoutRootStatus:
    assert_root_configuration_safe(config)
    status = get_checkout_root_status(config, name)
    if not status.available:
        raise CheckoutRootUnavailable(
            f"Checkout root '{name}' is unavailable: {status.reason}. Refusing to fall back or write beneath it."
        )
    if create:
        status.path.mkdir(parents=True, exist_ok=True)
    if not status.path.is_dir():
        raise CheckoutRootUnavailable(
            f"Checkout root '{name}' path '{status.path}' is not a directory."
        )
    return status


def preferred_checkout_root(config: Config, box_meta: BoxMeta) -> str:
    return load_placement(config, box_meta).authoritative_root


def local_data_path(config: Config, box_meta: BoxMeta) -> Path:
    placement = load_placement(config, box_meta)
    root_name = placement.authoritative_root
    root = config.configured_checkout_roots.get(root_name)
    if root is None:
        raise ValueError(
            f"Placement for '{box_meta.index_name}' refers to unknown checkout root '{root_name}'"
        )
    return root.path / box_meta.index_name


def get_box_checkout_status(config: Config, box_meta: BoxMeta) -> BoxCheckoutStatus:
    placement = load_placement(config, box_meta)
    root_name = placement.authoritative_root
    root = config.configured_checkout_roots.get(root_name)
    if root is None:
        return BoxCheckoutStatus(
            LocalCheckoutState.UNAVAILABLE,
            root_name,
            Path(f"<unknown-checkout-root:{root_name}>") / box_meta.index_name,
            None,
            placement,
        )
    root_status = get_checkout_root_status(config, root_name)
    path = root.path / box_meta.index_name
    if not root_status.available:
        state = (
            LocalCheckoutState.UNAVAILABLE
            if placement.state in (PlacementState.INCLUDED, PlacementState.RELOCATING)
            else LocalCheckoutState.EXCLUDED
        )
    elif placement.state == PlacementState.EXCLUDED:
        state = LocalCheckoutState.EXCLUDED
    elif not path.is_dir():
        state = LocalCheckoutState.MISSING
    elif placement.state == PlacementState.RELOCATING:
        state = LocalCheckoutState.RELOCATING
    else:
        state = LocalCheckoutState.INCLUDED
    return BoxCheckoutStatus(state, root_name, path, root_status, placement)


def set_box_placement(
    config: Config,
    box_meta: BoxMeta,
    root_name: str,
    state: PlacementState,
) -> CheckoutPlacement:
    if root_name not in config.configured_checkout_roots:
        raise ValueError(f"Unknown checkout root {root_name!r}")
    placement = CheckoutPlacement(checkout_root=root_name, state=state)
    save_placement(config, box_meta.box_id, placement)
    return placement


def mark_included(config: Config, box_meta: BoxMeta, root_name: str | None = None) -> CheckoutPlacement:
    current = load_placement(config, box_meta)
    selected = root_name if root_name is not None else current.authoritative_root
    require_checkout_root(config, selected, create=True)
    destination = config.configured_checkout_roots[selected].path / box_meta.index_name
    if destination.exists() and not destination.is_dir():
        raise FileExistsError(f"Checkout destination '{destination}' exists and is not a directory")
    return set_box_placement(config, box_meta, selected, PlacementState.INCLUDED)


def mark_excluded(config: Config, box_meta: BoxMeta) -> CheckoutPlacement:
    current = load_placement(config, box_meta)
    return set_box_placement(config, box_meta, current.authoritative_root, PlacementState.EXCLUDED)


def _copy_sparse_file(source: Path, destination: Path, mode: int) -> None:
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    source_fd = os.open(source, os.O_RDONLY)
    destination_fd = os.open(destination, flags, stat.S_IMODE(mode))
    try:
        size = os.fstat(source_fd).st_size
        if size == 0:
            return
        offset = 0
        sparse_supported = hasattr(os, "SEEK_DATA") and hasattr(os, "SEEK_HOLE")
        while sparse_supported and offset < size:
            try:
                data_offset = os.lseek(source_fd, offset, os.SEEK_DATA)
            except OSError as e:
                if e.errno == errno.ENXIO:
                    break
                if e.errno in (errno.EINVAL, errno.ENOTSUP):
                    sparse_supported = False
                    break
                raise
            hole_offset = os.lseek(source_fd, data_offset, os.SEEK_HOLE)
            os.lseek(source_fd, data_offset, os.SEEK_SET)
            os.lseek(destination_fd, data_offset, os.SEEK_SET)
            remaining = hole_offset - data_offset
            while remaining:
                chunk = os.read(source_fd, min(8 * 1024 * 1024, remaining))
                if not chunk:
                    raise OSError(f"Unexpected EOF while copying '{source}'")
                view = memoryview(chunk)
                while view:
                    written = os.write(destination_fd, view)
                    view = view[written:]
                remaining -= len(chunk)
            offset = hole_offset
        if not sparse_supported:
            os.lseek(source_fd, 0, os.SEEK_SET)
            os.lseek(destination_fd, 0, os.SEEK_SET)
            while chunk := os.read(source_fd, 8 * 1024 * 1024):
                view = memoryview(chunk)
                while view:
                    written = os.write(destination_fd, view)
                    view = view[written:]
        os.ftruncate(destination_fd, size)
        os.fsync(destination_fd)
    finally:
        os.close(destination_fd)
        os.close(source_fd)
    shutil.copystat(source, destination, follow_symlinks=False)


def copy_tree_preserving_layout(source: Path, destination: Path) -> None:
    """Copy a directory across filesystems, preserving links, metadata and holes."""
    if destination.exists():
        raise FileExistsError(destination)
    destination.mkdir(mode=stat.S_IMODE(source.stat().st_mode))
    hardlinks: dict[tuple[int, int], Path] = {}

    def copy_dir(src: Path, dst: Path) -> None:
        for entry in os.scandir(src):
            src_path = Path(entry.path)
            dst_path = dst / entry.name
            info = entry.stat(follow_symlinks=False)
            if stat.S_ISLNK(info.st_mode):
                os.symlink(os.readlink(src_path), dst_path)
                shutil.copystat(src_path, dst_path, follow_symlinks=False)
            elif stat.S_ISDIR(info.st_mode):
                dst_path.mkdir(mode=stat.S_IMODE(info.st_mode))
                copy_dir(src_path, dst_path)
                shutil.copystat(src_path, dst_path, follow_symlinks=False)
            elif stat.S_ISREG(info.st_mode):
                inode = (info.st_dev, info.st_ino)
                first = hardlinks.get(inode)
                if info.st_nlink > 1 and first is not None:
                    try:
                        os.link(first, dst_path)
                    except OSError:
                        _copy_sparse_file(src_path, dst_path, info.st_mode)
                else:
                    _copy_sparse_file(src_path, dst_path, info.st_mode)
                    if info.st_nlink > 1:
                        hardlinks[inode] = dst_path
            else:
                raise ValueError(
                    f"Cannot relocate special filesystem entry '{src_path}' (mode {oct(info.st_mode)}). "
                    "Sockets, devices and FIFOs are not portable checkout data."
                )

    copy_dir(source, destination)
    shutil.copystat(source, destination, follow_symlinks=False)


def _file_digest(path: Path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        while chunk := stream.read(8 * 1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _tree_manifest(root: Path) -> dict[str, tuple]:
    manifest: dict[str, tuple] = {}
    for current, dirnames, filenames in os.walk(root, followlinks=False):
        current_path = Path(current)
        names = sorted(dirnames + filenames)
        for name in names:
            path = current_path / name
            relative = path.relative_to(root).as_posix()
            info = path.lstat()
            mode = stat.S_IMODE(info.st_mode)
            if stat.S_ISLNK(info.st_mode):
                manifest[relative] = ("symlink", mode, os.readlink(path))
            elif stat.S_ISDIR(info.st_mode):
                manifest[relative] = ("directory", mode, info.st_mtime_ns)
            elif stat.S_ISREG(info.st_mode):
                # Hardlink topology is copied when the destination supports it;
                # content verification deliberately does not reject a filesystem
                # that cannot represent hardlinks.
                manifest[relative] = (
                    "file", mode, info.st_size, info.st_mtime_ns, _file_digest(path)
                )
            else:
                manifest[relative] = ("special", mode)
    return manifest


def verify_copied_tree(source: Path, destination: Path) -> None:
    source_manifest = _tree_manifest(source)
    destination_manifest = _tree_manifest(destination)
    if source_manifest != destination_manifest:
        source_keys = set(source_manifest)
        destination_keys = set(destination_manifest)
        details = []
        if source_keys != destination_keys:
            details.append(f"path sets differ (missing={sorted(source_keys - destination_keys)[:5]}, extra={sorted(destination_keys - source_keys)[:5]})")
        else:
            differing = [key for key in sorted(source_keys) if source_manifest[key] != destination_manifest[key]]
            details.append(f"metadata/content differs at {differing[:5]}")
        raise IOError(f"Relocation verification failed: {'; '.join(details)}")


def _same_filesystem(source: Path, destination_root: Path) -> bool:
    return source.stat().st_dev == destination_root.stat().st_dev


def _run_phase_hook(hook: Callable[[str], None] | None, phase: str) -> None:
    if hook is not None:
        hook(phase)


def relocate_box(
    config: Config,
    box_meta: BoxMeta,
    destination_root: str,
    *,
    phase_hook: Callable[[str], None] | None = None,
) -> Path:
    """Relocate one included checkout locally; no remote operation is performed.

    The caller must hold both the box lock and the global lock. Re-running this
    function with the same destination recovers every recorded interruption.
    ``phase_hook`` is an intentional test seam for crash/failure injection.
    """
    placement = load_placement(config, box_meta)
    if placement.state == PlacementState.RELOCATING:
        assert placement.relocation is not None
        if placement.relocation.destination_root != destination_root:
            raise RelocationInterrupted(
                f"'{box_meta.index_name}' has an interrupted relocation to "
                f"'{placement.relocation.destination_root}'. Recover that destination before choosing another."
            )
        return _recover_relocation(config, box_meta, placement, phase_hook=phase_hook)
    status = get_box_checkout_status(config, box_meta)
    if status.state != LocalCheckoutState.INCLUDED:
        raise ValueError(
            f"Cannot relocate '{box_meta.index_name}': checkout state is {status.state.value}, not included"
        )
    source_root = status.checkout_root
    if source_root == destination_root:
        raise ValueError(f"Box '{box_meta.index_name}' is already in checkout root '{destination_root}'")
    destination_status = require_checkout_root(config, destination_root, create=True)
    source_status = require_checkout_root(config, source_root)
    source = source_status.path / box_meta.index_name
    destination = destination_status.path / box_meta.index_name
    if not source.is_dir():
        raise FileNotFoundError(f"Recorded checkout source '{source}' does not exist")
    if destination.exists() or destination.is_symlink():
        raise FileExistsError(f"Checkout destination '{destination}' already exists")
    staging_name = f".{box_meta.index_name}.relocating-{uuid.uuid4().hex}"
    same_filesystem = _same_filesystem(source, destination_status.path)
    if not same_filesystem:
        required_bytes = sum(
            entry.stat(follow_symlinks=False).st_blocks * 512
            for directory, _dirs, files in os.walk(source)
            for entry in (Path(directory) / name for name in files)
            if not entry.is_symlink()
        )
        free_bytes = shutil.disk_usage(destination_status.path).free
        if free_bytes < required_bytes:
            raise OSError(
                f"Checkout root '{destination_root}' has {free_bytes} free bytes, but "
                f"relocating '{box_meta.index_name}' requires at least {required_bytes}."
            )
    relocation = RelocationRecord(
        source_root=source_root,
        destination_root=destination_root,
        staging_name=None if same_filesystem else staging_name,
        phase=RelocationPhase.MOVING if same_filesystem else RelocationPhase.COPYING,
    )
    placement = CheckoutPlacement(
        checkout_root=source_root,
        state=PlacementState.RELOCATING,
        relocation=relocation,
    )
    save_placement(config, box_meta.box_id, placement)
    _run_phase_hook(phase_hook, "recorded")
    return _recover_relocation(config, box_meta, placement, phase_hook=phase_hook)


def _recover_relocation(
    config: Config,
    box_meta: BoxMeta,
    placement: CheckoutPlacement,
    *,
    phase_hook: Callable[[str], None] | None = None,
) -> Path:
    assert placement.relocation is not None
    record = placement.relocation
    source_status = require_checkout_root(config, record.source_root)
    destination_status = require_checkout_root(config, record.destination_root, create=True)
    source = source_status.path / box_meta.index_name
    destination = destination_status.path / box_meta.index_name
    staging = destination_status.path / record.staging_name if record.staging_name else None

    if record.phase == RelocationPhase.COPYING:
        assert staging is not None
        if destination.exists():
            if not source.exists():
                raise RelocationInterrupted(
                    f"Relocation destination '{destination}' exists but source '{source}' is missing; inspect both before recovery"
                )
            verify_copied_tree(source, destination)
            record.phase = RelocationPhase.COMMITTED
            placement.checkout_root = record.destination_root
            save_placement(config, box_meta.box_id, placement)
        else:
            if not source.is_dir():
                raise RelocationInterrupted(f"Relocation source '{source}' is missing")
            if staging.exists():
                shutil.rmtree(staging)
            copy_tree_preserving_layout(source, staging)
            _run_phase_hook(phase_hook, "copied")
            verify_copied_tree(source, staging)
            record.phase = RelocationPhase.DESTINATION_READY
            save_placement(config, box_meta.box_id, placement)
            _run_phase_hook(phase_hook, "verified")

    if record.phase == RelocationPhase.DESTINATION_READY:
        assert staging is not None
        if destination.exists():
            if staging.exists():
                raise RelocationInterrupted(
                    f"Both relocation staging '{staging}' and destination '{destination}' exist"
                )
        else:
            if not staging.is_dir():
                raise RelocationInterrupted(f"Verified relocation staging '{staging}' is missing")
            os.replace(staging, destination)
        record.phase = RelocationPhase.COMMITTED
        placement.checkout_root = record.destination_root
        save_placement(config, box_meta.box_id, placement)
        _run_phase_hook(phase_hook, "committed")

    if record.phase == RelocationPhase.MOVING:
        if source.exists() and destination.exists():
            raise RelocationInterrupted(f"Both relocation source '{source}' and destination '{destination}' exist")
        if source.exists():
            os.replace(source, destination)
        elif not destination.is_dir():
            raise RelocationInterrupted(
                f"Neither relocation source '{source}' nor destination '{destination}' exists"
            )
        record.phase = RelocationPhase.COMMITTED
        placement.checkout_root = record.destination_root
        save_placement(config, box_meta.box_id, placement)
        _run_phase_hook(phase_hook, "committed")

    if record.phase == RelocationPhase.COMMITTED:
        if not destination.is_dir():
            raise RelocationInterrupted(f"Committed relocation destination '{destination}' is missing")
        # Group links are derived and replaced before the only remaining source
        # copy is removed. If link rebuilding fails, the committed placement and
        # both complete copies make recovery safe and discoverable.
        from ._models import create_user_box_group_symlinks
        create_user_box_group_symlinks(config)
        _run_phase_hook(phase_hook, "links_updated")
        if source.exists():
            verify_copied_tree(source, destination)
            shutil.rmtree(source)
        _run_phase_hook(phase_hook, "source_deleted")
        final = CheckoutPlacement(
            checkout_root=record.destination_root,
            state=PlacementState.INCLUDED,
        )
        save_placement(config, box_meta.box_id, final)
        _run_phase_hook(phase_hook, "finalized")
        return destination

    raise AssertionError(f"Unhandled relocation phase {record.phase}")
